solution:
from collections import Counter

def count_zero_picks(a: list[int], b: list[int], c: list[int], d: list[int]) -> int:
    pair_sums = Counter(x + y for x in a for y in b)       # how many (i, j) give each sum
    return sum(pair_sums[-(x + y)] for x in c for y in d)

perf.naive:
from collections import Counter

def count_zero_picks(a: list[int], b: list[int], c: list[int], d: list[int]) -> int:
    last = Counter(d)
    total = 0
    for x in a:
        for y in b:
            for z in c:                    # one lookup saves a loop, still O(n³)
                total += last[-(x + y + z)]
    return total
